import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.B5WAEDB7.js";const c=JSON.parse('{"title":"Flow per Button aus einem Eintrag starten","description":"Über ein Feld vom Typ „Interne Verknüpfung\\" einen Button anzeigen, der einen Flow mit Bezug zum Eintrag startet.","frontmatter":{"title":"Flow per Button aus einem Eintrag starten","description":"Über ein Feld vom Typ „Interne Verknüpfung\\" einen Button anzeigen, der einen Flow mit Bezug zum Eintrag startet."},"headers":[],"relativePath":"grids/flow-button.md","filePath":"grids/flow-button.md","lastUpdated":1786353399000}'),a={name:"grids/flow-button.md"};function s(l,e,o,d,u,g){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="flow-per-button-aus-einem-eintrag-starten" tabindex="-1">Flow per Button aus einem Eintrag starten <a class="header-anchor" href="#flow-per-button-aus-einem-eintrag-starten" aria-label="Permalink to &quot;Flow per Button aus einem Eintrag starten&quot;">​</a></h1><p>Ein Feld vom Typ <strong>Interne Verknüpfung</strong> kann statt auf ein Grid, ein Formular oder eine Seite auch auf einen <strong>Link</strong> verweisen — den Freigabelink eines Formulars oder den Start-Link eines Flows. Ein solcher Wert wird nicht als Text, sondern als <strong>Button</strong> angezeigt. Klickt jemand darauf, öffnet sich das Ziel und erfährt dabei, <strong>von welchem Eintrag</strong> der Klick ausging.</p><p>Das unterscheidet diesen Weg von einem einfachen <a href="/referenz/spaltentypen#weblink">Weblink-Feld</a>: Ein Weblink öffnet nur die gespeicherte Adresse. Der Button aus einer Internen Verknüpfung übergibt zusätzlich den Bezug zum Eintrag.</p><h2 id="voraussetzung" tabindex="-1">Voraussetzung <a class="header-anchor" href="#voraussetzung" aria-label="Permalink to &quot;Voraussetzung&quot;">​</a></h2><p>Ein Flow mit dem Auslöser <strong>Seite anzeigen</strong>. Dieser Auslöser stellt den Start-Link bereit, auf den das Feld verweisen kann.</p><p>→ <a href="/flows/trigger#seite-anzeigen">Trigger</a></p><div class="tip custom-block"><p class="custom-block-title">Auch für Formulare</p><p>Genauso funktioniert es mit dem <a href="/formulare/formular-teilen">Freigabelink eines Formulars</a>. Der Button ist dann nicht auf Flows beschränkt.</p></div><h2 id="einrichten" tabindex="-1">Einrichten <a class="header-anchor" href="#einrichten" aria-label="Permalink to &quot;Einrichten&quot;">​</a></h2><ol><li>Legen Sie im Grid ein Feld vom Typ <strong>Interne Verknüpfung</strong> an.</li><li>Prüfen Sie in den Feldeinstellungen, dass unter den zulässigen Zieltypen <strong>Link</strong> aktiviert ist. Standardmäßig ist er es.</li><li>Öffnen Sie das Feld in der gewünschten Zeile und wählen Sie aus der Liste den Start-Link des Flows (oder den Freigabelink des Formulars) aus.</li></ol><p>Die Zelle zeigt jetzt einen Button statt eines Textwerts.</p><h2 id="was-beim-klick-ubergeben-wird" tabindex="-1">Was beim Klick übergeben wird <a class="header-anchor" href="#was-beim-klick-ubergeben-wird" aria-label="Permalink to &quot;Was beim Klick übergeben wird&quot;">​</a></h2><p>ApptiveGrid öffnet das Ziel in einem Overlay und hängt an dessen Adresse zwei Parameter an:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Inhalt</th></tr></thead><tbody><tr><td><code>entityUri</code></td><td>die vollständige Adresse des Eintrags</td></tr><tr><td><code>entityId</code></td><td>die ID des Eintrags</td></tr></tbody></table><p>Damit kann das Ziel — ein Flow oder ein Formular — auf genau diesen Eintrag Bezug nehmen, statt kontextlos zu starten.</p><div class="warning custom-block"><p class="custom-block-title">Kein Ersatz für vorausgefüllte Werte</p><p><code>entityUri</code> und <code>entityId</code> identifizieren den Eintrag, sie füllen keine Felder aus. Sollen konkrete Werte im Ziel bereits ausgefüllt sein, kombinieren Sie das mit <a href="/formulare/vorausgefuellte-links">vorausgefüllten Links</a> beim Formular bzw. mit einem Schritt, der die ID im Flow nachschlägt.</p></div><h2 id="typische-anwendungen" tabindex="-1">Typische Anwendungen <a class="header-anchor" href="#typische-anwendungen" aria-label="Permalink to &quot;Typische Anwendungen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Anwendung</th><th>Ablauf</th></tr></thead><tbody><tr><td>Freigabeprozess anstoßen</td><td>Button „Freigeben&quot; auf dem Eintrag startet einen Flow, der den Status setzt</td></tr><tr><td>Folgeaktion für genau diese Zeile</td><td>Ein Flow verarbeitet, aktualisiert oder verschickt etwas bezogen auf den Eintrag</td></tr><tr><td>Geführten Prozess mit Bezug zum Datensatz starten</td><td>Der Flow beginnt mit einer Seite, die weiß, von welchem Eintrag sie aufgerufen wurde</td></tr></tbody></table><h2 id="auch-in-geteilten-ansichten" tabindex="-1">Auch in geteilten Ansichten <a class="header-anchor" href="#auch-in-geteilten-ansichten" aria-label="Permalink to &quot;Auch in geteilten Ansichten&quot;">​</a></h2><p>Der Button erscheint ebenso in einer <a href="/ansichten/ansicht-teilen">geteilten Ansicht</a>. Damit können auch Personen ohne ApptiveGrid-Konto eine Aktion zu einem bestimmten Eintrag auslösen — etwa eine externe Person, die eine Anfrage bestätigt.</p><div class="warning custom-block"><p class="custom-block-title">Zugriff auf die Ansicht ist nicht gleich Zugriff auf den Flow</p><p>Wer den Button sieht, kann ihn klicken. Prüfen Sie, ob der ausgelöste Flow selbst noch einmal absichern muss, wer die dahinterliegende Aktion tatsächlich ausführen darf.</p></div><h2 id="weiter" tabindex="-1">Weiter <a class="header-anchor" href="#weiter" aria-label="Permalink to &quot;Weiter&quot;">​</a></h2><ul><li><a href="/referenz/spaltentypen#interne-verknuepfung">Spaltentypen-Referenz</a></li><li><a href="/flows/trigger">Trigger</a></li><li><a href="/formulare/formular-teilen">Formular teilen</a></li><li><a href="/grids/verknuepfungen">Grids verknüpfen</a></li></ul>',22)])])}const f=t(a,[["render",s]]);export{c as __pageData,f as default};
